#!/usr/bin/env python3
"""English editorial layer for the unchanged FES-Bench evidence snapshot.

The supplied reasoning outline sets the explanatory order. Archived reports and
metric tables supply measurements. Historical claims are not promoted to scores.
"""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1];D=json.loads((R/'data/review_data.json').read_text())
entries=[
('E001','Matched temperature-tail tests','Model comparison','Completed, bounded','Ti / Zr / SiO₂','Can a learned model beat a simple function under the same label budget?','Direct Thermo4 has lower test ΔG MAE than the compared learned models. An analytic residual fit shows no consistent gain from the declared QH baseline.','These are fixed-pressure, known-phase tests. The test tails contain no reference transitions. Do not use them to rank zero-label transfer.'),
('E002','Structure-to-coefficient transfer','Transfer','Two folds completed','SiO₂ / Ti','Can structure predict thermodynamic coefficients without target free-energy labels?','C-simple has lower target-pair MAE than C-DPA in the SiO₂ cristobalite LOPO and Ti LOSO folds. Both match the SiO₂ envelope event. Neither matches the Ti event.','One held-out phase and one held-out system are not a broad material survey. Matched T2/T3 transfer remains open.'),
('E003','Rebuild the historical Hf prediction','Implementation audit','Historical checkpoint','Hf','Does inference apply the baseline, atom count and learned correction correctly?','The selected seed-11, step-1500 reconstruction agrees with archived inference. The first large error appears in the learned correction. The old initializer had only Si/O types.','This result applies to one old checkpoint. It does not describe later compatible initializers or prove that every historical run was correct.'),
('E004','Hf-compatible initialization','Model comparison','Completed, one system','Hf','Does a compatible element map remove the fit gap?','The compatible checkpoint loads and uses the correct Hf type index. Matched T2/T3 runs still trail analytic controls.','A valid type map does not prove useful thermodynamic pretraining. Keep each training recipe and seed separate.'),
('E005','Batch size and training budget','Optimization','Completed, bounded','Hf','Does the training recipe explain part of the error?','Batch 8 improves T3 in the two tested seeds. T2 test error does not improve. A longer T2 run reduces training error without a matching test gain.','The longer run also changes learning-rate decay. This is not a pure step-count ablation. Seed spread measures training variability, not predictive uncertainty.'),
('E006','Task branches and alternate initialization','Initialization','Partly complete','Hf','Do task branches explain the pairwise prediction error?','Branches in the same frozen shared descriptor give nearly identical pair predictions.','This is not a contrast between independent descriptors. An HfO₂ branch is not proof of elemental-Hf pretraining.'),
('E007','Relative slope and curvature','Physical diagnostics','Descriptive evidence','Ti / Zr / Hf / SiO₂','Does a model preserve the temperature response of the phase gap?','The archived Hf T2 curve has a large relative-slope error. Curvature error changes with the smoothing window.','These derivatives come from smooth reference tables. Window sensitivity prevents a stable curvature ranking or a causal attribution.'),
('E008','Frameworks and input budgets','Benchmark protocol','Historical matrix','Eight-system scope','Which methods can enter each task with legal inputs?','The A–G register separates method applicability, available results and information budgets.','The old matrix predates the two C transfer folds. Its entry that C had not run is now historical.'),
('E009','Frozen splits and event definitions','Benchmark protocol','Implemented; comparisons open','Core systems','Can the test measure a stable transition without selecting it from the reference curve?','The temperature-tail split uses T/P grids. Pair crossings and stable-envelope transitions have separate scores.','With no reference test event, recall and matched Tc error are not applicable. False predicted events can still be counted.'),
('E010','Static DFT and reference checks','Reference construction','Completed, static only','Ti / Zr / Hf / SiO₂','Do structures and Hamiltonians support a meaningful energy comparison?','Ten new W1 static calculations support targeted Hf k-point, SiO₂ Hamiltonian and structure checks.','Static total energies do not provide finite-temperature G. Compatible zero points and settings remain essential.'),
('E011','Carbon paired QHA grid','Reference construction','Scoped layer admitted','C','Can both phases be compared on the same temperature-pressure grid?','The admitted grid contains 32 phase-G and 16 paired-ΔG states. The volume, phonon and independent reconstruction records are available.','This is quantum-harmonic QHA at Te = 0. Numerical bounds omit full systematics. The sign at 10 GPa and 1200 K is unresolved within the recorded bound.'),
('E012','Ti hcp QHA comparison surface','Reference construction','Comparison layer admitted','Ti','What single-phase QHA response can be reproduced?','The package contains 217 F(V,T) and 155 G(T,P) rows, with q-mesh and fit sensitivities.','The calculation fixes c/a and Te = 0. It does not provide hcp–bcc ΔG or an anharmonic reference. Several convergence errors remain unknown.'),
('E013','Four-phase SiO₂ source tables','Source recovery','Source layer admitted','SiO₂','Does the fourth phase lack G, or does it lack a matched input contract?','The source-v2 package contains 1,649 G rows per phase and 9,894 derived pair rows. Its exact pressure is 0.0001 GPa.','Source reuse is not new DFT. Uncertainty and covariance are unknown. Structural matching remains a separate requirement.'),
('E014','Ti/Zr/Hf source archives','Source recovery','Provenance checked','Ti / Zr / Hf','Can the original TI and effective-harmonic assets be traced?','Six phase archives were recovered and checked. The audit corrected the use of a representative structure hash as a source-G structure hash.','G is an ensemble quantity. It need not map to one unique microscopic structure per row. Some reference conventions and errors remain unknown.'),
('E015','Six-phase phonon checks','Reference construction','Completed; interpretation updated','MgSiO₃ / C / CaSiO₃','Which phases need a different free-energy route?','Fifty displacement outputs passed the force-output audit. Soft modes were found. Later fine-k graphite checks removed the old Γ shear instability.','One stable central volume does not validate a whole QHA grid. The old graphite rejection was superseded by later numerical checks.'),
('E016','MgSiO₃ PPv soft-mode route','Open production','Not closed','MgSiO₃','Can a compatible two-phase reference be completed?','Small-amplitude fixed-cell curvature and the supercell contrast support a soft mode under the tested settings.','Do not remove imaginary modes and call the result ordinary QHA. The new finite-temperature or integration route has not closed the paired grid.'),
('E017','Ca volume brackets and phase identity','Open production','Not closed','CaSiO₃','Does sampling represent the target state and yield a two-phase reference?','The V319 mean T/P is near the target, but distortion coordinates have few effective samples. Two tetragonal volumes have F(V,T) candidates.','Short MD is not a free energy. Average P1 symmetry alone does not reject the phase. Keep new PBE-D3(BJ) and source DP-LDA layers separate.'),
('E018','Fe sampling and TI paths','Open production','Path revised; no new integral','Fe','Can the sampled reference path connect to the target phases?','Twelve source fcc/hcp pairs have scoped admission. After disorder in the SC→DP midpoint, a direct Einstein→DP route was started.','No complete new TI/FEP label has been delivered. The anchor does not fill missing bcc data. QE and VASP reference layers remain distinct.'),
('E019','Historical figures and manuscript gaps','Evidence control','Historical / open','Paper-wide','Which claims have valid evidence, and which remain placeholders?','Historical seed-23 figures, old QH definitions, corrected runs and pending result slots remain explicitly marked.','A figure placeholder is not a result. A single-system diagnostic must not become a general model claim.')]
cards=[]
for eid,title,category,state,systems,question,observation,limit in entries:
 old=next(c for c in D['cards'] if c['id']==eid)
 cards.append(dict(id=eid,title=title,category=category,state=state,systems=systems,question=question,observation=observation,limit=limit,evidence=old['evidence']))
hypotheses=[
 dict(id='H0',title='QH + residual should give a large accuracy gain.',state='Not established',question='Does the same function fit better after a physical baseline is added?',observation='The matched analytic controls show no consistent pairwise gain. Early SiO₂ tests used historical protocols and cannot establish a common ranking.',control='Compare direct Thermo4 with baseline + the same four-term residual. Keep labels, splits and selection fixed.',next='Test whether the baseline helps with less target information or with an unseen phase.',evidence=['E001','E003','E019']),
 dict(id='H1',title='QH supplies useful temperature dependence.',state='Clue, not a transfer result',question='Can a thermal-shape gain preserve the phase gap?',observation='Historical anchored single-phase curves motivated this idea. Phase-specific offsets can still change ΔG and reverse the phase order.',control='Measure single-phase shape, pairwise gap and slope separately. State the actual QH definition.',next='Use a valid QHA layer and compare a matched smooth temperature prior.',evidence=['E003','E007','E012','E015']),
 dict(id='H2',title='Mean ΔG error does not determine phase accuracy.',state='Bounded counterexample',question='Can a lower mean error still select the wrong stable phase?',observation='Yes. In the two SiO₂ test seeds, the Phase-ID MLP has lower mean MAE than T3 but zero stable-envelope accuracy. T3 reaches 100%.',control='Inspect the gap between the lowest two phases and the direction of its prediction error.',next='Locate the pair that reverses the stable envelope. The test has no reference transition.',evidence=['E001','E009']),
 dict(id='H3',title='Structure can predict transferable thermodynamic coefficients.',state='Two folds tested',question='Can a model predict a new phase or system without its free-energy labels?',observation='C-simple has lower target-pair MAE than C-DPA in the two completed folds. This does not prove a general descriptor ranking.',control='Use source-only selection. Match target-label budgets, baselines and energy references.',next='Complete more LOPO/LOSO folds and seeds, plus matched T2/T3 transfer.',evidence=['E002','E008']),
 dict(id='H4',title='A physical baseline helps when it adds missing task information.',state='Open causal question',question='Does QHA add transferable information beyond a smooth temperature function?',observation='The present results do not isolate a causal vibration, electronic or magnetic contribution to model error.',control='Match the Hamiltonian, nuclear statistics, electronic temperature, reference gauge and legal inputs.',next='Compare direct shape, QHA residual and simple structural controls on an admitted layer.',evidence=['E001','E007','E011','E012','E015'])]
stages=[
 dict(id='start',title='Start with residual learning',question='Can a physical baseline simplify G?',answer='Early SiO₂ tests motivated the idea. Their targets and protocols differ from the later matched tests.',limit='Keep early metrics out of the current leaderboard.',experiments=['E019']),
 dict(id='audit',title='Check the formula before the physics',question='Does inference implement the declared model?',answer='Historical static-energy double counting required a correction. The selected Hf reconstruction later passed.',limit='One passed checkpoint does not validate every historical run.',experiments=['E003','E004','E006']),
 dict(id='fit',title='Add the analytic control',question='Is the temperature function itself difficult to fit?',answer='Thermo4 fits the known-phase tails well. Adding the declared QH baseline gives no consistent pairwise gain.',limit='The control uses target training labels. It is not zero-shot.',experiments=['E001','E005']),
 dict(id='decision',title='Separate error from phase decisions',question='Does lower MAE imply the correct stable phase?',answer='The two SiO₂ seeds provide a counterexample. Event scores also require an actual reference event.',limit='Phase classification in a tail is not boundary recovery.',experiments=['E001','E007','E009']),
 dict(id='transfer',title='Test unseen phases and systems',question='Can structure predict coefficients without target labels?',answer='The C readout now has one SiO₂ LOPO and one Ti LOSO result. C-simple has lower pair MAE in both.',limit='Two folds do not establish broad transfer or its cause.',experiments=['E002','E008']),
 dict(id='reference',title='Make the reference target comparable',question='Do the labels describe compatible physics?',answer='Carbon has a scoped paired QHA grid. Ti has a single-phase QHA layer. Other source and production layers remain separate.',limit='Eight indexed systems do not mean eight complete grids.',experiments=['E010','E011','E012','E013','E014','E015','E016','E017','E018'])]
systems={
 'SiO2':dict(note='Four source phases are available at 0.0001 GPa. Uncertainty and covariance are unknown. Structural matching is a separate input requirement.',task='Multiphase stability; leave-one-phase-out transfer.',state='Source layer admitted',evidence=['E013']),
 'Ti':dict(note='Source hcp/bcc curves and the new hcp QHA control are different layers. The new control fixes c/a and Te = 0.',task='Family transfer; single-phase QHA comparison.',state='Source admission pending; QHA control admitted',evidence=['E012','E014']),
 'Zr':dict(note='Source hcp/bcc curves are traced. Their presence does not complete the current reference contract.',task='Family leave-one-system-out transfer.',state='Source admission pending',evidence=['E014']),
 'Hf':dict(note='Several initialization, batch and budget protocols exist. Scores must retain their protocol and seed.',task='Family transfer; fit and implementation diagnostics.',state='Source admission pending',evidence=['E003','E004','E005','E014']),
 'C':dict(note='32 phase-G and 16 paired-ΔG states cover four pressures and four temperatures. This is a quantum-harmonic QHA layer, not full anharmonic truth.',task='Pressure-dependent paired evaluation within the scoped layer.',state='Paired QHA layer admitted',evidence=['E011']),
 'MgSiO3':dict(note='The source QMC/DFPT-QHA layer and new DFT work are separate. PPv soft-mode diagnostics have not closed a new paired grid.',task='Tasks require a compatible admitted layer.',state='New paired grid open',evidence=['E016']),
 'CaSiO3':dict(note='Source DP-LDA points, new PBE-D3(BJ) candidates and finite-temperature MD have different roles. Tetragonal F(V,T) is not a cubic–tetragonal ΔG.',task='Sparse relative-G tasks after reference checks.',state='New paired grid open',evidence=['E017']),
 'Fe':dict(note='Twelve source fcc/hcp pairs have scoped admission. The new integration path and missing bcc coverage remain open.',task='Pointwise pair and stability tasks at admitted states.',state='Source pairs admitted; new integral open',evidence=['E018'])}
# Report numbers are retained with explicit source IDs and display precision.
controls=[dict(system='Ti',direct=0.035,residual=0.265,unit='meV/atom',protocol='Ti matched batch-8 temperature tail',source='S00001'),dict(system='Zr',direct=0.194,residual=0.188,unit='meV/atom',protocol='Zr matched batch-8 temperature tail',source='S00001'),dict(system='Hf',direct=0.235,residual=0.234,unit='meV/atom',protocol='Hf matched control; separate split',source='S00013'),dict(system='SiO₂',direct=0.03732,residual=0.03736,unit='meV/atom',protocol='SiO₂ three-phase matched temperature tail',source='S00001')]
content=dict(cards=cards,hypotheses=hypotheses,stages=stages,systems=systems,controls=controls,
 snapshot_sha256=hashlib.sha256((R/'data/review_data.json').read_bytes()).hexdigest(),
 logic='The supplied first-principles outline sets the explanatory order. Measurements retain archived source, protocol and scope.',
 language='English, short direct sentences; scientific terms defined where needed.')
(R/'data/explainer_content.json').write_text(json.dumps(content,ensure_ascii=False,indent=2))
(R/'data/explainer_content.js').write_text('window.FES_EXPLAINER='+json.dumps(content,ensure_ascii=False)+';\n')
print('English layer:',len(cards),'experiments,',len(hypotheses),'hypotheses,',len(stages),'stages')
if __name__=='__main__':pass
